//! Bulk data tables for the BC6H block packer: per-mode endpoint
//! significant-bit counts, the bit-layout programs that scatter endpoint bits
//! into each of the 14 BC6H modes, and the 32 two-subset partition patterns
//! (the first 32 BC7 patterns, with anchor texels flagged).

// Anchor flags are stored in decimal and the per-mode bit-layout programs are
// concatenated into one linear table, indexed through BC6H_LAYOUT_OFFSETS.

/// One step of a BC6H mode's bit-layout program: which endpoint value to read
/// (`comp` 0-2 = R/G/B, 3 = partition pattern; `index`
/// = subset*2 + low/high) and which of its bits to emit. `first_bit == -1`
/// emits the single bit `last_bit`; otherwise the run between `first_bit` and
/// `last_bit` inclusive is emitted, reversed when `first_bit > last_bit`.
#[repr(C)]
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Bc6hBitLayout {
    pub comp: i8,
    pub index: i8,
    pub last_bit: i8,
    pub first_bit: i8,
}

/// Endpoint significant-bit counts per BC6H mode: `[mode]` yields base bits
/// then per-channel delta bits (direct bits for the non-delta modes 9 and 10).
/// Modes 0-9 are 2-subset, 10-13 are 1-subset.
pub static BC6H_MODE_SIG_BITS: [[u8; 4]; 14] = [
    [10, 5, 5, 5],
    [7, 6, 6, 6],
    [11, 5, 4, 4],
    [11, 4, 5, 4],
    [11, 4, 4, 5],
    [9, 5, 5, 5],
    [8, 6, 5, 5],
    [8, 5, 6, 5],
    [8, 5, 5, 6],
    [6, 6, 6, 6],
    [10, 10, 10, 10],
    [11, 9, 9, 9],
    [12, 8, 8, 8],
    [16, 4, 4, 4],
];

