#[cfg(test)]
mod offset_tests {
    use super::{BC6H_BIT_LAYOUTS, BC6H_LAYOUT_OFFSETS};

    /// The hand-spelled offsets must match a sentinel scan of the table.
    #[test]
    fn layout_offsets_match_sentinel_scan() {
        let mut ofs = [0usize; 14];
        let mut mode = 1;
        for (i, step) in BC6H_BIT_LAYOUTS.iter().enumerate() {
            if step.comp == -1 && mode < 14 {
                ofs[mode] = i + 1;
                mode += 1;
            }
        }
        assert_eq!(ofs, BC6H_LAYOUT_OFFSETS);
    }
}
